const raw = $('Webhook').first().json.body;
const b = (raw && typeof raw === 'object' && !Array.isArray(raw)) ? raw : {};
const cfg = $('Config').first().json;
const run_id = 'run-' + Date.now() + '-' + Math.random().toString(36).slice(2, 8);
const errors = [];
const CTRL = /[\u0000-\u001f\u007f]/;
const LEGACY = ['jjbags-in', 'jj-bags-com', 'jjbags', 'jj-bags', 'jjbags.in', 'jj-bags.com', 'sa', 'qubix', 'qubix-sa', 'automation', 'www', 'fleet'];
const isStr = (v) => typeof v === 'string';
const slug = isStr(b.slug) ? b.slug : '';
if (!/^[a-z][a-z0-9-]{1,20}$/.test(slug)) errors.push('slug must match ^[a-z][a-z0-9-]{1,20}$');
if (LEGACY.includes(slug)) errors.push('slug is reserved (legacy site)');
for (const f of ['clientName', 'businessName']) {
const v = b[f];
if (!isStr(v) || v.trim().length === 0) errors.push(f + ' is required');
else if (v.length > 80) errors.push(f + ' must be <= 80 chars');
else if (CTRL.test(v)) errors.push(f + ' must not contain control characters');
}
const email = isStr(b.adminEmail) ? b.adminEmail : '';
if (email.length > 254 || !/^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,}$/.test(email)) errors.push('adminEmail is not a valid email');
let brandColor = '';
if (b.brandColor !== undefined && b.brandColor !== null && b.brandColor !== '') {
if (!isStr(b.brandColor) || !/^#[0-9a-fA-F]{6}$/.test(b.brandColor)) errors.push('brandColor must match ^#[0-9a-fA-F]{6}$');
else brandColor = b.brandColor;
}
let extra = 0;
if (b.debug_extra_reserve_mib !== undefined && b.debug_extra_reserve_mib !== null) {
const d = b.debug_extra_reserve_mib;
if (typeof d !== 'number' || !Number.isFinite(d) || d < 0) errors.push('debug_extra_reserve_mib must be a number >= 0');
else extra = d;
}
const ok = errors.length === 0;
const safeSlug = (isStr(b.slug) ? b.slug : '').replace(/[^\x20-\x7e]/g, '?').slice(0, 40);
const now = new Date().toISOString();
return [{ json: {
ok, run_id, cfg, errors,
input: ok ? { slug, clientName: b.clientName, businessName: b.businessName, adminEmail: email, brandColor, debug_extra_reserve_mib: extra } : null,
resp_code: 422,
resp: { status: 'invalid', run_id, errors },
rec: { run_id, slug: safeSlug, attempt_no: 0, phase: 'preflight', started_at: now, finished_at: now, exit_code: null, classification: 'invalid', decision: 'invalid_input', capacity_json: '', output_tail: '', note: errors.join('; ').slice(0, 500) },
} }];

const v = $('Validate').first().json;
const row = $input.first().json || {};
let exists = false, why = '';
if (row.slug === v.input.slug) {
const t = Date.parse(row.updated_at || row.updatedAt || '');
if (row.status === 'provisioning' && Number.isFinite(t) && (Date.now() - t) < 2 * 3600 * 1000) { exists = true; why = 'provisioning in progress'; }
else if (row.status === 'active') { exists = true; why = 'client already active'; }
// N2: `live` is the status the two seeded legacy rows carry, and the one an operator
// would hand-set for a stack this workflow did not provision. Either way it names a
// running store, so the claim upsert must never reach it.
else if (row.status === 'live') { exists = true; why = 'a live client already owns this slug'; }
else if (row.legacy === true || row.read_only === true) { exists = true; why = 'slug belongs to a read-only legacy site'; }
}
const now = new Date().toISOString();
const cfg = v.cfg;
// C2 step (1): the row this run is about to claim as `provisioning`. It is written
// BEFORE the pre-flight SSH so a concurrent run's Evaluate can see this run in
// flight. Reached only on the exists === false branch, i.e. only after the checks
// above have already stopped the run for any pre-existing active / in-progress /
// legacy row — so the claim can never overwrite a real client's row.
const claim = exists ? null : {
slug: v.input.slug, client_name: v.input.clientName, business_name: v.input.businessName,
subdomain: v.input.slug + '.' + cfg.domain,
site_url: 'https://' + v.input.slug + '.' + cfg.domain,
admin_url: 'https://' + v.input.slug + '.' + cfg.domain + '/admin',
status: 'provisioning', last_run_id: v.run_id, est_ram_mib: Number(cfg.per_client_mib),
legacy: false, read_only: false, updated_at: now,
};
return [{ json: {
exists, resp_code: 409, claim,
resp: { status: 'conflict', reason: why, run_id: v.run_id },
rec: { run_id: v.run_id, slug: v.input.slug, attempt_no: 0, phase: 'preflight', started_at: now, finished_at: now, exit_code: null, classification: 'conflict', decision: 'slug_exists_in_registry', capacity_json: '', output_tail: '', note: why },
} }];

const v = $('Validate').first().json;
const q = (s) => "'" + String(s).replace(/'/g, "'\\''") + "'";
// I2: `docker compose ls` cannot see a client whose containers were removed, but
// its named volumes (and therefore its data) still exist. Claiming that slug would
// let a later transient failure run `down -v` against a real client's volumes, so
// the volume namespace is checked too. The slug is regex-validated in Validate.
const volRe = '(^|_)qubix-' + v.input.slug + '-(mysql|redis)$';
const cmd = "echo '##MEM'; free -m | awk '/^Mem:/{print $7}'; echo '##NPROC'; nproc; echo '##LOAD'; cat /proc/loadavg; " +
"echo '##DISK'; p=/var/lib/docker; [ -d \"$p\" ] || p=/; df -Pm \"$p\" | awk 'NR==2{print $4}'; " +
"echo '##PROJECTS'; docker compose ls -a -q; echo \"##DOCKER_RC=$?\"; " +
"echo '##VOLUMES'; vl=$(docker volume ls -q); vrc=$?; echo \"$vl\" | grep -E " + q(volRe) + "; echo \"##VOL_RC=$vrc\"; " +
"echo '##END'";
return [{ json: { ...v, preflight_cmd: cmd, preflight_started_at: new Date().toISOString() } }];

const v = $('Validate').first().json;
const cfg = v.cfg;
const started = $('Prep Preflight').first().json.preflight_started_at;
const r = $('Preflight SSH').first().json || {};
const finished = new Date().toISOString();
const extra = v.input.debug_extra_reserve_mib || 0;
const perClient = Number(cfg.per_client_mib);

// C2 step (2): count OTHER runs currently in flight and charge each of them a full
// per-client budget. This run's own row was already written as `provisioning`
// BEFORE the pre-flight SSH (write-then-read), so two same-moment runs each see the
// other and both block — fail closed — instead of both reading the same free -m.
const INFLIGHT_MAX_AGE_MS = 2 * 3600 * 1000;
const inflight = [];
for (const it of $input.all()) {
const row = (it && it.json) || {};
if (typeof row.slug !== 'string' || row.slug === '' || row.slug === v.input.slug) continue;
if (row.status !== 'provisioning') continue;
const t = Date.parse(row.updated_at || row.updatedAt || '');
if (!Number.isFinite(t) || (Date.now() - t) >= INFLIGHT_MAX_AGE_MS) continue;
inflight.push(row.slug);
}
const inflight_count = inflight.length;
const reserveBase = Number(cfg.reserve_mib);
const reserve = reserveBase + extra + inflight_count * perClient;

let decision = 'blocked_preflight_failed', reasons = [], cap = {}, projects = [], volumes = [], owned = false;
const sshOk = r.error === undefined && r.code === 0 && typeof r.stdout === 'string';
if (!sshOk) {
reasons.push('pre-flight SSH failed: ' + String((r.error && (r.error.message || r.error)) || 'no successful result (connection failure or missing exit status)').slice(0, 200));
} else {
const sec = {};
let cur = null;
for (const line of r.stdout.split('\n')) {
const m = line.trim().match(/^##([A-Z_]+)(?:=(.*))?$/);
if (m) { cur = m[1]; sec[cur] = m[2] !== undefined ? [m[2]] : []; }
else if (cur && line.trim() !== '') sec[cur].push(line.trim());
}
const avail = Number((sec.MEM || [])[0]);
const nproc = Number((sec.NPROC || [])[0]);
const lp = ((sec.LOAD || [])[0] || '').split(/\s+/).map(Number);
const disk = Number((sec.DISK || [])[0]);
const rc = (sec.DOCKER_RC || [])[0];
const vrc = (sec.VOL_RC || [])[0];
const parsed = [avail, nproc, disk, lp[0], lp[1], lp[2]].every((n) => Number.isFinite(n)) && nproc > 0 && rc === '0' && vrc === '0' && sec.END !== undefined;
if (!parsed) {
reasons.push('pre-flight output unparseable, or the docker project/volume listing failed');
} else {
projects = sec.PROJECTS || [];
volumes = sec.VOLUMES || [];
const load5pc = lp[1] / nproc;
const fit = Math.max(0, Math.floor((avail - reserve) / perClient));
const ramOk = (avail - reserve) >= perClient;
const cpuOk = load5pc <= Number(cfg.max_load_per_core);
const diskOk = disk >= Number(cfg.min_free_disk_mib);
cap = { available_mib: avail, nproc, load1: lp[0], load5: lp[1], load15: lp[2], load5_per_core: Math.round(load5pc * 1000) / 1000,
free_disk_mib: disk, per_client_mib: perClient, reserve_mib: reserveBase, debug_extra_reserve_mib: extra,
inflight_count, inflight_slugs: inflight, inflight_reserve_mib: inflight_count * perClient, reserve_effective_mib: reserve,
max_load_per_core: Number(cfg.max_load_per_core), min_free_disk_mib: Number(cfg.min_free_disk_mib),
clients_that_fit: fit, checks: { ram: ramOk, cpu: cpuOk, disk: diskOk }, project_count: projects.length, stray_volume_count: volumes.length };
if (projects.includes('qubix-' + v.input.slug)) { decision = 'slug_taken'; reasons.push('project qubix-' + v.input.slug + ' already exists'); }
else if (volumes.length > 0) { decision = 'slug_taken'; reasons.push('docker volume(s) for this slug already exist (a client whose containers were removed still owns its data): ' + volumes.join(', ')); }
else if (!ramOk || !cpuOk || !diskOk) {
decision = 'blocked_capacity';
if (!ramOk) reasons.push('RAM: available ' + avail + ' - reserve ' + reserve + ' (base ' + reserveBase + ' + debug ' + extra + ' + ' + inflight_count + ' in-flight x ' + perClient + ') < per-client ' + perClient);
if (!cpuOk) reasons.push('CPU: load5/core ' + cap.load5_per_core + ' > ' + cfg.max_load_per_core);
if (!diskOk) reasons.push('disk: free ' + disk + ' MiB < ' + cfg.min_free_disk_mib);
} else { decision = 'proceed'; owned = true; }
}
}
const proceed = decision === 'proceed';
const recDecision = { proceed: 'proceed', slug_taken: 'slug_taken', blocked_capacity: 'blocked — insufficient capacity', blocked_preflight_failed: 'blocked_preflight_failed' }[decision];
const resp_code = { proceed: 202, slug_taken: 409, blocked_capacity: 503, blocked_preflight_failed: 503 }[decision];
const now = new Date().toISOString();
const state = {
...v, decision, proceed, owned_by_run: owned, capacity: cap, reasons, attempt_no: 0, history: [],
resp_code,
resp: proceed ? { status: 'accepted', run_id: v.run_id, slug: v.input.slug, capacity: { available_mib: cap.available_mib, clients_that_fit: cap.clients_that_fit, inflight_count } }
: { status: decision, run_id: v.run_id, reasons, capacity: cap.available_mib === undefined ? null : { available_mib: cap.available_mib, clients_that_fit: cap.clients_that_fit, inflight_count, checks: cap.checks } },
rec: { run_id: v.run_id, slug: v.input.slug, attempt_no: 0, phase: 'preflight', started_at: started, finished_at: finished, exit_code: sshOk ? 0 : (typeof r.code === 'number' ? r.code : null),
classification: proceed ? 'ok' : (decision === 'slug_taken' ? 'terminal' : 'blocked'), decision: recDecision, capacity_json: JSON.stringify(cap), output_tail: '', note: reasons.join('; ').slice(0, 500) },
client: { slug: v.input.slug, client_name: v.input.clientName, business_name: v.input.businessName, subdomain: v.input.slug + '.' + cfg.domain,
site_url: 'https://' + v.input.slug + '.' + cfg.domain, admin_url: 'https://' + v.input.slug + '.' + cfg.domain + '/admin', status: 'provisioning',
last_run_id: v.run_id, est_ram_mib: perClient, legacy: false, read_only: false, updated_at: now },
// C2 step (3): every non-deploying outcome resets THIS run's own claim so it does
// not hold a phantom per-client reservation for the next two hours. The reset node
// matches on slug AND last_run_id = this run id, so a row belonging to any other
// run (or a real client) can never be touched by it.
reset: { slug: v.input.slug, last_run_id: v.run_id, status: decision, updated_at: now },
alert_to: cfg.alert_email,
alert_subject: '[Qubix fleet] Onboarding BLOCKED for ' + v.input.slug + ': ' + recDecision,
alert_text: 'Onboarding of "' + v.input.slug + '" was stopped BEFORE any deployment action.\nDecision: ' + recDecision + '\nReasons: ' + reasons.join('; ') + '\nCapacity: ' + JSON.stringify(cap) + '\nRun: ' + v.run_id,
};
return [{ json: state }];

const s = $('Evaluate').first().json;
return [{ json: { alert_to: s.alert_to, alert_subject: s.alert_subject, alert_text: s.alert_text,
run_id: s.run_id, slug: s.input.slug, attempt_no: 0, alert_kind: s.decision } }];

const st = $input.first().json;
const cfg = st.cfg, inp = st.input;
const attempt_no = (st.attempt_no || 0) + 1;
if (attempt_no > Number(cfg.max_attempts)) throw new Error('attempt bound exceeded');
if (st.proceed !== true) throw new Error('deploy reached without a proceed decision');
const q = (s) => "'" + String(s).replace(/'/g, "'\\''") + "'";
let args = ' --slug=' + q(inp.slug) + ' --client-name=' + q(inp.clientName) + ' --business-name=' + q(inp.businessName) + ' --admin-email=' + q(inp.adminEmail);
if (inp.brandColor) args += ' --brand-color=' + q(inp.brandColor);
const dir = cfg.base_dir + '/qubix-' + inp.slug;
// I3 + N1: claim-once ownership marker, inside .git so it never dirties the checkout.
// The marker is CLAIMED, not overwritten: if it already exists holding a different run
// id, this run refuses to touch the checkout at all and exits 2 (terminal — no retry,
// no teardown). That closes the same-slug double-admit window, where two runs are both
// admitted, both see the slug free in the pre-flight, and the second would otherwise
// take ownership of the first's stack and later `down -v` its MySQL volume.
// Writing the same run id again is fine, so a run's own retry attempts still pass.
// A successful, owned teardown deletes the marker, so re-onboarding after a
// failed_escalated run is not blocked; after a failed_teardown the marker legitimately
// stays and an operator must clear it (see README, stranded state).
//
// M1: the claim is ATOMIC. `set -C` (noclobber) makes the shell open the marker with
// O_EXCL, so the existence test and the write are one syscall — the old
// `if [ -e ] … ; echo > marker` was check-then-write, and two same-slug runs that both
// reached it before either wrote could both pass the check and both proceed. Now
// exactly one creator can win. Three outcomes, distinguished after a failed create:
//   marker absent  -> the create failed for some other reason (unwritable .git, full
//                     disk): MARKER_WRITE_FAILED, exit 10, transient, retryable.
//   marker == ours -> this run's own retry re-entering; proceed, as before.
//   marker != ours -> FOREIGN_MARKER, exit 2, terminal, no deploy and no teardown.
const cmd = 'd=' + q(dir) + '; m="$d/.git/fleet-run-id"; r=' + q(st.run_id) + '; '
+ '[ -d "$d/.git" ] || git clone --branch fleet --depth 1 ' + q(cfg.repo_url) + ' "$d" || exit 10; '
+ '(set -C; echo "$r" > "$m") 2>/dev/null || { '
+ '[ -e "$m" ] || { echo MARKER_WRITE_FAILED; exit 10; }; '
+ '[ "$(cat "$m" 2>/dev/null)" = "$r" ] || { echo FOREIGN_MARKER; exit 2; }; }; '
+ 'cd "$d" || exit 10; '
+ 'scripts/provision-client.sh' + args;
return [{ json: { ...st, attempt_no, deploy_cmd: cmd, attempt_started_at: new Date().toISOString() } }];

const st = $('Prep Deploy').item.json;
const r = $input.first().json || {};
const cfg = st.cfg;
const errored = r.error !== undefined;
const code = (!errored && typeof r.code === 'number') ? r.code : null;
let cls;
if (code === 0) cls = 'success';
else if (code !== null && code >= 1 && code <= 9) cls = 'terminal';
else cls = 'transient';

// I1: redaction must not hinge on one exact sentence. ANSI decoration is stripped
// first; the known wording is tried, then a generic "password...: <value>" form;
// and whatever happened, a blanket second pass scrubs every remaining
// password/secret/token assignment before anything is persisted or emailed.
const stripAnsi = (s) => String(s === undefined || s === null ? '' : s)
.replace(/\u001b\[[0-9;?]*[ -\/]*[@-~]/g, '')
.replace(/\u001b[@-_]/g, '')
.replace(/\r/g, '');
const out = errored ? '' : stripAnsi(r.stdout);
const err = errored ? String((r.error && (r.error.message || r.error)) || 'ssh error') : stripAnsi(r.stderr);
let password = '';
const m1 = out.match(/Admin password \(generated, shown once\): (\S+)/);
if (m1) password = m1[1];
if (!password) {
const m2 = out.match(/password[^\n:=]*[:=][ \t]*(\S+)/i);
if (m2 && m2[1] !== '[REDACTED]') password = m2[1];
}
const password_captured = password !== '';
const redact = (s) => {
let t = String(s);
if (password) t = t.split(password).join('[REDACTED]');
t = t.replace(/(password[^\n:=]*[:=][ \t]*)\S+/gi, '$1[REDACTED]');
t = t.replace(/((?:secret|token|passphrase|api[_-]?key)[^\n:=]*[:=][ \t]*)\S+/gi, '$1[REDACTED]');
return t;
};
const tail = redact(out + (err ? '\n--stderr--\n' + err : '')).slice(-4000);
const foreignMarker = /(^|\n)FOREIGN_MARKER(\n|$)/.test(out);
const now = new Date().toISOString();
const history = [...(st.history || []), { attempt_no: st.attempt_no, exit_code: code, classification: cls, tail }];
let next, mode = null, status = null, note;
if (cls === 'success') {
next = 'success'; status = 'active';
note = password_captured ? 'provisioned' : 'provisioned, but the generated admin password could NOT be read from the output — it must be reset by hand';
}
else if (cls === 'terminal') {
next = 'stop'; status = 'failed_terminal';
// N1: exit 2 also covers the claim-once marker refusing a foreign checkout.
note = foreignMarker
? ('terminal: ' + cfg.base_dir + '/qubix-' + st.input.slug + '/.git/fleet-run-id holds ANOTHER run id, so this run refused the checkout (FOREIGN_MARKER). Nothing was deployed and NO teardown was attempted. Another run owns that stack, or an earlier run\'s teardown never completed — confirm no stack is running for this slug, then clear the stale marker by hand (README: stranded state).')
: ('terminal exit ' + code + ': not retried, no teardown');
}
else if (!st.owned_by_run) { next = 'stop'; status = 'failed_escalated'; note = 'transient failure but project not proven owned by this run: no teardown'; }
else { next = 'teardown'; mode = st.attempt_no < Number(cfg.max_attempts) ? 'retry' : 'final'; note = 'transient (' + (errored ? 'ssh error' : 'exit ' + code) + '), attempt ' + st.attempt_no + '/' + cfg.max_attempts + ', ' + mode; }
const client = { ...st.client, status: status || 'provisioning', updated_at: now };
const allTails = history.map((h) => 'attempt ' + h.attempt_no + ' exit=' + h.exit_code + ' ' + h.classification + ':\n' + h.tail).join('\n\n');
const s2 = { ...st, history, last_class: cls, last_code: code, next, teardown_mode: mode, client,
secret_password: password, password_captured,
rec: { run_id: st.run_id, slug: st.input.slug, attempt_no: st.attempt_no, phase: 'deploy', started_at: st.attempt_started_at, finished_at: now, exit_code: code, classification: cls, decision: 'deploy_attempt', capacity_json: '', output_tail: tail, note },
alert_to: cfg.alert_email,
alert_subject: '[Qubix fleet] Onboarding ' + (status || 'failed') + ' for ' + st.input.slug,
alert_text: 'Onboarding of "' + st.input.slug + '" stopped with status ' + status + '.\n' + note + '\nRun: ' + st.run_id + '\n\nOutput (redacted) of every attempt:\n' + allTails };
delete s2.deploy_cmd;
// N5: the password only ever has a reason to exist on the success path, which goes
// straight to the credentials email. On any other path this state is carried into the
// retry loop and through `Backoff Wait` — and n8n persists a waiting execution's data
// regardless of the save-execution settings once the wait is long enough.
if (cls !== 'success') s2.secret_password = '';
return [{ json: s2 }];

const st = $('Classify').item.json;
const c = st.client;
// N6: Mark Active continues on failure, so say so here rather than letting the client be
// provisioned with nobody told and the registry row silently stuck at provisioning.
// Same detection as Registry Eval: n8n hides the item-level error, so success is judged
// by whether Mark Active handed back the row it was supposed to write.
let regFailed = false;
try {
const it = $('Mark Active').item;
const reg = (it && it.json) || {};
const errObj = it && it.error !== undefined ? it.error : reg.error;
regFailed = (errObj !== undefined && errObj !== null)
|| !(reg.slug === st.input.slug && typeof reg.id === 'number' && reg.status === 'active');
} catch (e) { /* if it cannot be read, do not invent a warning */ }
// Caddy registration (Prep Caddy -> Caddy SSH -> Caddy Eval -> Rec Caddy) is chained
// AFTER the whole credentials pipeline (Rec Delivery), not before or parallel to it --
// deliberately, so a slow/hung Caddy SSH call can never delay the one-time password
// email. (An earlier parallel-branch design was tried and measured to still
// serialize behind whichever sibling branch this n8n instance's scheduler happened
// to run first, regardless of connection-array order -- an explicit sequential
// dependency is the only way that was actually proven, empirically, to guarantee
// credentials go out first.) Caddy Eval's result is therefore never available when
// this code runs, so it cannot be surfaced here; its outcome is fully recorded via
// Rec Caddy's provision_attempts row (phase 'caddy') instead. See
// docker/n8n/README.md's Caddy section.
const regWarning = regFailed
? '\n\nWARNING: the fleet_clients registry row could NOT be updated after 3 tries. The client IS\n'
+ 'provisioned and the password above is valid, but its row still shows `provisioning` (which also\n'
+ 'holds a capacity reservation for 2h) — set it to active by hand.'
: '';
// I1: never send a credentials email with a blank credential. If the password was
// not captured, this becomes an ACTION REQUIRED alert carrying no credential at all.
const captured = st.password_captured === true && typeof st.secret_password === 'string' && st.secret_password.length > 0;
const head = 'Client "' + st.input.clientName + '" (' + st.input.slug + ') was provisioned.\nSite: ' + c.site_url + '\nAdmin: ' + c.admin_url + '\nAdmin email: ' + st.input.adminEmail + '\n';
const subject = captured
? '[Qubix fleet] Client provisioned: ' + st.input.slug
: '[Qubix fleet] ACTION REQUIRED — provisioned WITHOUT a captured password: ' + st.input.slug;
const text = captured
? head + 'Admin password (shown once): ' + st.secret_password + '\nRun: ' + st.run_id
: head + '\nThe generated admin password could NOT be read from the provisioning output, so it is\n'
+ 'not in this message and is not stored anywhere. The client admin password must be\n'
+ 'RESET BY HAND — see docker/n8n/README.md, "Resetting a client admin password by hand".\nRun: ' + st.run_id;
return [{ json: { alert_to: st.cfg.alert_email, alert_subject: subject, alert_text: text + regWarning,
run_id: st.run_id, slug: st.input.slug, attempt_no: st.attempt_no, password_captured: captured } }];

const s = $('Classify').item.json;
return [{ json: { alert_to: s.alert_to, alert_subject: s.alert_subject, alert_text: s.alert_text,
run_id: s.run_id, slug: s.input.slug, attempt_no: s.attempt_no, alert_kind: s.client.status } }];

const st = $input.first().json;
if (st.owned_by_run !== true || st.next !== 'teardown') throw new Error('teardown forbidden: not owned by this run');
const q = (s) => "'" + String(s).replace(/'/g, "'\\''") + "'";
const slug = st.input.slug, base = st.cfg.base_dir;
const proj = q('qubix-' + slug);
const dir = base + '/qubix-' + slug;
// I3: defence at the point of destruction. `down -v` destroys a MySQL volume, so it
// runs only if the checkout still carries THIS run's ownership marker. On a mismatch
// nothing is torn down, NOT_OWNER is printed, and the run stops as failed_teardown.
//
// Finding 1: "marker absent" and "marker holds a foreign run id" are NOT the same
// thing and must not produce the same token. The marker is claimed BEFORE
// provision-client.sh can run (see Prep Deploy), so an absent marker proves nothing
// was ever created for this slug — the usual cause is the `git clone` failing, the
// most likely first-production failure of all. That is safe and retryable; a foreign
// marker is another run's live stack and must stay terminal. NO_MARKER exits 0
// without running `down`, exactly as NOT_OWNER does — there is nothing to tear down.
//
// Finding 2: the exit status of `down -v` (DOWN_RC) and of the project listing
// (LS_RC) are both captured AND both acted on here. If the docker daemon is
// unreachable mid-teardown, `down -v` fails and `docker compose ls` fails too — its
// stdout is then empty, so a bare `grep -qx` finds no match and the old command
// concluded the project was gone, printed GONE and DELETED the ownership marker,
// although nothing had been torn down. GONE is now emitted (and the marker released)
// only when the listing succeeded, does not contain the project, AND `down -v` itself
// exited 0. Every other combination keeps the marker and names which check failed.
const cmd = 'd=' + q(dir) + '; m="$d/.git/fleet-run-id"; '
+ '[ -e "$m" ] || { echo NO_MARKER; exit 0; }; '
+ '[ "$(cat "$m" 2>/dev/null)" = ' + q(st.run_id) + ' ] || { echo NOT_OWNER; exit 0; }; '
+ 'cd "$d" || exit 10; '
+ 'docker compose -f ' + q('docker-compose.' + slug + '.yml') + ' -p ' + proj + ' down -v --remove-orphans; '
+ 'rc=$?; echo "DOWN_RC=$rc"; '
+ 'p=$(docker compose ls -a -q); lsrc=$?; echo "LS_RC=$lsrc"; '
// N1: release the claim-once marker, but ONLY once ownership was proven above AND the
// project is confirmed gone — so a later re-onboarding of this slug is not blocked
// forever, while a failed teardown deliberately leaves the marker in place.
+ 'if [ "$lsrc" != 0 ]; then echo LS_FAILED; '
+ 'elif printf \'%s\\n\' "$p" | grep -qx ' + proj + '; then echo STILL_PRESENT; '
+ 'elif [ "$rc" != 0 ]; then echo DOWN_FAILED; '
+ 'else rm -f "$m"; echo GONE; fi';
return [{ json: { ...st, teardown_cmd: cmd, teardown_started_at: new Date().toISOString() } }];

const st = $('Prep Teardown').item.json;
const r = $input.first().json || {};
const cfg = st.cfg;
const errored = r.error !== undefined;
const out = errored ? '' : String(r.stdout || '');
// Minor 11: this tail is persisted to provision_attempts, which outlives every other
// record here, so it goes through the same blanket scrub Classify applies instead of
// being stored raw. No secret can plausibly reach `docker compose down -v` output
// today; this is defence in depth, not a known leak.
const redact = (s) => {
let t = String(s === undefined || s === null ? '' : s);
if (typeof st.secret_password === 'string' && st.secret_password !== '') t = t.split(st.secret_password).join('[REDACTED]');
t = t.replace(/(password[^\n:=]*[:=][ \t]*)\S+/gi, '$1[REDACTED]');
t = t.replace(/((?:secret|token|passphrase|api[_-]?key)[^\n:=]*[:=][ \t]*)\S+/gi, '$1[REDACTED]');
return t;
};
const notOwner = /(^|\n)NOT_OWNER(\n|$)/.test(out);
// Finding 1: an ABSENT marker is not a foreign marker. Prep Deploy claims the marker
// before provision-client.sh can run, so NO_MARKER proves nothing was created for this
// slug (the usual cause being a failed `git clone`, exit 10). Treating that as
// NOT_OWNER used to end the run as failed_teardown — terminal, never retried — with a
// note claiming another run owned the checkout, which was both wrong and the reason a
// plain network blip at clone time could not self-heal. It now follows exactly the
// path a successful, empty teardown follows: retry if attempts remain, otherwise
// failed_escalated. NOT_OWNER is unchanged — that one is the real safety guard.
const noMarker = !notOwner && /(^|\n)NO_MARKER(\n|$)/.test(out);
// Finding 2: DOWN_RC was captured and never read. If the docker daemon is unreachable
// mid-teardown, BOTH `down -v` and the `docker compose ls` check fail; grep then sees
// empty input, matches nothing, and the old logic concluded GONE — removing the
// ownership marker although nothing had been torn down. GONE now additionally requires
// the recorded exit status of `down -v` to be exactly 0; missing or non-zero is not gone.
// LS_RC is the same story for the listing that decides "is the project still there".
// A missing code is treated as a failure, not as a pass.
const rcMatch = out.match(/(^|\n)DOWN_RC=(-?\d+)(\s|$)/);
const down_rc = rcMatch ? Number(rcMatch[2]) : null;
const lsMatch = out.match(/(^|\n)LS_RC=(-?\d+)(\s|$)/);
const ls_rc = lsMatch ? Number(lsMatch[2]) : null;
const gone = !errored && r.code === 0 && down_rc === 0 && ls_rc === 0 && /(^|\n)GONE\s*$/.test(out) && !/STILL_PRESENT/.test(out) && !/LS_FAILED/.test(out) && !/DOWN_FAILED/.test(out) && !notOwner && !noMarker;
const tail = redact(errored ? String((r.error && (r.error.message || r.error)) || 'ssh error') : out + String(r.stderr || '')).slice(-4000);
const now = new Date().toISOString();
let status = null, cont = false, note;
if (notOwner) {
status = 'failed_teardown';
note = 'NOT_OWNER: ' + cfg.base_dir + '/qubix-' + st.input.slug + '/.git/fleet-run-id does not hold this run id, so `docker compose down -v` was NOT executed — another run owns this checkout. Stopping; never retried.';
} else if (noMarker) {
if (st.teardown_mode === 'retry') { cont = true; note = 'NO_MARKER: ' + cfg.base_dir + '/qubix-' + st.input.slug + '/.git/fleet-run-id does not exist, so this run never claimed the checkout and nothing was created to tear down (a failed clone is the usual cause). Nothing to undo; retrying after backoff.'; }
else { status = 'failed_escalated'; note = 'attempts exhausted; NO_MARKER: the checkout was never claimed, so nothing had been created and no teardown was needed'; }
} else if (!gone) {
status = 'failed_teardown';
note = 'teardown did not prove project gone (' + (errored ? 'ssh error' : 'down exit ' + (down_rc === null ? 'not reported' : down_rc) + ', project listing exit ' + (ls_rc === null ? 'not reported' : ls_rc)) + '); the ownership marker was deliberately NOT released; retrying would hit the slug-collision check (exit 2), stopping';
} else if (st.teardown_mode === 'retry') { cont = true; note = 'teardown ok, retrying after backoff'; }
else { status = 'failed_escalated'; note = 'attempts exhausted, teardown ok'; }
const client = { ...st.client, status: status || 'provisioning', updated_at: now };
const allTails = (st.history || []).map((h) => 'attempt ' + h.attempt_no + ' exit=' + h.exit_code + ' ' + h.classification + ':\n' + h.tail).join('\n\n');
return [{ json: { ...st, teardown_ok: gone, not_owner: notOwner, no_marker: noMarker, down_rc, ls_rc, continue_retry: cont, client,
rec: { run_id: st.run_id, slug: st.input.slug, attempt_no: st.attempt_no, phase: 'teardown', started_at: st.teardown_started_at, finished_at: now, exit_code: errored ? null : (typeof r.code === 'number' ? r.code : null), classification: gone ? 'ok' : (notOwner ? 'not_owner' : (noMarker ? 'no_marker' : 'failed')), decision: 'teardown', capacity_json: '', output_tail: tail, note },
alert_to: cfg.alert_email,
alert_subject: '[Qubix fleet] Onboarding ' + status + ' for ' + st.input.slug,
alert_text: 'Onboarding of "' + st.input.slug + '" ended with status ' + status + '.\n' + note + '\nRun: ' + st.run_id + '\n\nOutput (redacted) of every attempt:\n' + allTails + '\n\nTeardown output:\n' + tail } }];

const s = $('Teardown Eval').item.json;
return [{ json: { alert_to: s.alert_to, alert_subject: s.alert_subject, alert_text: s.alert_text,
run_id: s.run_id, slug: s.input.slug, attempt_no: s.attempt_no, alert_kind: s.client.status } }];

// C1: credential delivery is failure-tolerant (Send Credentials retries, then
// continues), and its outcome is recorded as a provision_attempts row so a lost
// email is visible without ever opening n8n execution data. No secret goes in here.
let meta;
try { meta = $('Build Credentials Email').item.json; }
catch (e) { meta = $('Build Credentials Email').last().json; }
const r = $input.first().json || {};
const accepted = Array.isArray(r.accepted) ? r.accepted.length : 0;
const rejected = Array.isArray(r.rejected) ? r.rejected.length : 0;
const failed = r.error !== undefined || rejected > 0 || accepted === 0;
const now = new Date().toISOString();
const notes = [];
if (failed) {
notes.push('credentials email NOT delivered (' + String(r.error || ('accepted=' + accepted + ', rejected=' + rejected)).slice(0, 160) + ')');
notes.push('the generated admin password was NOT delivered and is stored nowhere — reset the client admin password BY HAND (see the README section on resetting a client admin password by hand)');
} else {
notes.push('credentials email delivered');
}
if (meta.password_captured !== true) notes.push('password was not captured from the provisioning output either');
return [{ json: { rec: {
run_id: meta.run_id, slug: meta.slug, attempt_no: meta.attempt_no, phase: 'credentials',
started_at: now, finished_at: now, exit_code: null,
classification: failed ? 'delivery_failed' : 'delivered', decision: 'credentials_delivery',
capacity_json: '', output_tail: '', note: notes.join('; ').slice(0, 500),
} } }];

// I4: Send Alert retries, then continues. When the alert still could not be
// delivered, record it — otherwise a failed run's only trace is a row nobody reads.
// Only ONE of the three Build Alert nodes can run in a given execution.
let meta = null;
for (const n of ['Build Alert Blocked', 'Build Alert Stop', 'Build Alert Final']) {
try { const items = $(n).all(); if (items && items.length) meta = items[items.length - 1].json; } catch (e) { /* branch not taken */ }
}
if (!meta) meta = { run_id: '', slug: '', attempt_no: 0, alert_kind: 'unknown' };
const r = $input.first().json || {};
const accepted = Array.isArray(r.accepted) ? r.accepted.length : 0;
const rejected = Array.isArray(r.rejected) ? r.rejected.length : 0;
const failed = r.error !== undefined || rejected > 0 || accepted === 0;
if (!failed) return [];
const now = new Date().toISOString();
return [{ json: { rec: {
run_id: meta.run_id, slug: meta.slug, attempt_no: meta.attempt_no || 0, phase: 'alert',
started_at: now, finished_at: now, exit_code: null,
classification: 'alert_failed', decision: 'alert_delivery',
capacity_json: '', output_tail: '',
note: ('alert "' + (meta.alert_kind || 'unknown') + '" could not be delivered after retries ('
+ String(r.error || ('accepted=' + accepted + ', rejected=' + rejected)).slice(0, 160)
+ ') — this run ended without anyone being notified by email').slice(0, 500),
} } }];

// N6: `Mark Active` retries then CONTINUES, so a Data Table failure can no longer end
// the run before the credentials email. Emits a row ONLY when the registry write
// ultimately failed, so the operator learns the client is provisioned while its
// fleet_clients row is still stuck at `provisioning`. Carries no secret.
//
// How the failure is detected: n8n STRIPS the item-level `error` before a Code node
// sees it (verified against this n8n build: on failure the item is exactly
// {json, pairedItem} and json is the UNCHANGED INPUT state, i.e. Classify's item;
// on success json is the written registry row). So the discriminator is "did Mark
// Active hand back the row it was supposed to write". The `error` probes are kept as a
// belt-and-braces signal in case a future n8n version does surface it.
const st = $('Classify').item.json;
const it = $input.first() || {};
const j = it.json || {};
const errObj = it.error !== undefined ? it.error : j.error;
const wroteRow = j.slug === st.input.slug && typeof j.id === 'number' && j.status === 'active';
const failed = (errObj !== undefined && errObj !== null) || !wroteRow;
if (!failed) return [];
const msg = String((errObj && (errObj.message || errObj.description)) || errObj
|| 'the node returned no written row (n8n hides the underlying error from this node)').slice(0, 160);
const now = new Date().toISOString();
return [{ json: { rec: {
run_id: st.run_id, slug: st.input.slug, attempt_no: st.attempt_no, phase: 'registry',
started_at: now, finished_at: now, exit_code: null,
classification: 'mark_active_failed', decision: 'registry_update',
capacity_json: '', output_tail: '',
note: ('the client WAS provisioned, but its fleet_clients row could not be set to active after 3 tries ('
+ msg + ') — the row still shows `provisioning`, which also holds a per-client capacity '
+ 'reservation for 2h. Set it to active by hand.').slice(0, 500),
} } }];

const st = $('Classify').item.json;
const slug = st.input.slug;
const dir = st.cfg.base_dir + '/qubix-' + slug;
const q = (s) => "'" + String(s).replace(/'/g, "'\\''") + "'";
const blockFile = '/tmp/qubix-caddy-' + slug + '.block';
const cmd = 'cd ' + q(dir) + ' && scripts/generate-caddy-block.sh --slug=' + q(slug)
+ ' > ' + q(blockFile)
+ ' && scripts/apply-caddy-block.sh --slug=' + q(slug) + ' --target-dir=' + q('/opt/qubix') + ' --block-file=' + q(blockFile)
+ '; rc=$?; rm -f ' + q(blockFile) + '; exit $rc';
return [{ json: { ...st, caddy_cmd: cmd, caddy_started_at: new Date().toISOString() } }];

const st = $('Prep Caddy').item.json;
const r = $input.first().json || {};
const errored = r.error !== undefined;
const code = (!errored && typeof r.code === 'number') ? r.code : null;
const success = code === 0;
const stripAnsi = (s) => String(s === undefined || s === null ? '' : s)
.replace(/\u001b\[[0-9;?]*[ -\/]*[@-~]/g, '')
.replace(/\u001b[@-_]/g, '')
.replace(/\r/g, '');
const out = errored ? '' : stripAnsi(r.stdout);
const err = errored ? String((r.error && (r.error.message || r.error)) || 'ssh error') : stripAnsi(r.stderr);
const tail = (out + (err ? '\n--stderr--\n' + err : '')).slice(-2000);
const now = new Date().toISOString();
return [{ json: {
caddy_success: success,
rec_caddy: { run_id: st.run_id, slug: st.input.slug, attempt_no: st.attempt_no, phase: 'caddy',
started_at: st.caddy_started_at, finished_at: now, exit_code: code, classification: success ? 'success' : 'failed',
decision: 'caddy_register', capacity_json: '', output_tail: tail,
note: success ? ('Caddy site block registered for ' + st.client.subdomain)
: ('Caddy site block registration FAILED for ' + st.client.subdomain + ' (exit ' + code + (errored ? ', ssh error' : '') + '). The client is provisioned and reachable; only the friendly subdomain is affected. See docker/n8n/README.md to register it by hand.') },
} }];
